[
  {
    "statement": "A before-and-after, site comparison study found no increase in the spawning stock biomass of cod following a temporary fishery closure over nine years, compared to fished areas.",
    "citations": [
      "2664"
    ]
  },
  {
    "statement": "Evidence on long-term closures reported mixed abundance outcomes.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Two site comparison studies found a higher abundance of only one of seven fish species in areas closed to groundfish fisheries for six to eight years compared to open areas.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Two site comparison studies found a lower abundance of monkfish in areas closed to groundfish fisheries for six to eight years compared to open areas.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "One replicated, before-and-after study found more young salmon returning to rivers in the five years after a long-term coastal fishery closure.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "One replicated, before-and-after study found similar numbers of older salmon returning to rivers in the five years after a long-term coastal fishery closure.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Another replicated, before-and-after study found lesser sandeel biomass and density peaked but showed no overall increase over three years after a long-term fishery closure.",
    "citations": [
      "2655"
    ]
  }
]

[
  {
    "statement": "Prohibiting all fishing in Marine Protected Areas (MPAs) for 1 to over 25 years often corresponded with higher fish species richness in 14 site-comparison studies.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Six site-comparison studies found similar fish species richness between areas with and without fishing prohibitions.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One systematic review found no difference in fish species richness between areas with and without fishing prohibitions.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "In seven studies, fish community composition in no-fishing areas differed from community composition in fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Thirty of 54 site-comparison studies and five of six reviews reported higher fish abundance or biomass in no-fishing Marine Protected Areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Eight studies found similar fish abundances between no-fishing Marine Protected Areas and fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Sixteen studies found mixed effects on fish abundance, with results varying by species, trophic level, size, duration, or habitat.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One study reported long-term declines of some sharks in areas where enforcement of fishing prohibitions was poor.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "In Marine Protected Areas with zonation, no-fishing or no-entry zones had higher species numbers than partially fished zones and unprotected areas after 10 to 15 years.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "No-fishing or no-entry zones had greater fish biomass or abundance than fished zones and outside areas after 3 to 27 years.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The effects of protection on fish biomass or abundance in zoned Marine Protected Areas varied by fish group, size, reef region, and protection level.",
    "citations": [
      "2674"
    ]
  }
]

[
  {
    "statement": "Evidence indicates that modifying longline configuration can reduce unwanted shark and ray catches.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "Increasing lead weight on mid-water longlines to increase the sinking rate reduced catches of unwanted sharks and rays.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "Using nylon instead of wire hook attachments reduced unwanted shark and ray catches in some cases.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "Deploying fishing gear at selected depths reduced unwanted catches of some shark and ray species in replicated studies.",
    "citations": [
      "2683"
    ]
  },
  {
    "statement": "Deploying fishing gear above the seabed instead of on the seabed reduced unwanted catches of some shark and ray species.",
    "citations": [
      "2683"
    ]
  }
]

[
  {
    "statement": "Evidence from North Sea studies indicates several trawl-gear modifications are available to reduce unwanted catches of cod and haddock.",
    "citations": []
  },
  {
    "statement": "A separator trawl separated unwanted cod into a lower codend.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "The lower codend of the separator trawl had a larger mesh that allowed more smaller cod to escape.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Topless, or coverless, trawls reduced unwanted Atlantic cod.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls reduced unwanted larger haddock but not smaller haddock.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "In one of two cases, larger cod reductions occurred when using topless trawls.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Size-sorting escape grids fitted to trawl nets reduced unwanted sizes of cod and other non-target fish, including haddock, in multiple regions that include the North Sea.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "In North Sea and Norwegian Sea studies, size-sorting escape grids improved size-selection for haddock.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "In North Sea and Norwegian Sea studies, size-sorting escape grids did not consistently improve size-selection for cod.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "One study found that size-sorting escape grids provided no improvement for cod size-selection compared to square-mesh windows.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Fitting mesh escape panels or windows to trawl nets reduced unwanted catches, including cod and haddock, in several North Sea studies.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Reviews and experiments reported that mesh escape panels improved size-selectivity for Atlantic cod and haddock.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "The effects of mesh escape panels on selectivity varied by the panel's design and position.",
    "citations": [
      "2716"
    ]
  },
  {
    "statement": "Modifying the position and/or size of mesh escape panels improved size-selectivity for haddock in North Sea studies.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "Some studies reported no reduction in unwanted cod when modifying the position or size of mesh escape panels.",
    "citations": [
      "2717"
    ]
  }
]

[
  {
    "statement": "Across trawl fisheries, size-sorting escape grids frequently reduced unwanted fish catches.",
    "citations": [
      "2720",
      "2721"
    ]
  },
  {
    "statement": "Size-sorting escape grids sometimes improved size-selectivity in trawl fisheries.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "In fish trawls, size-sorting escape grids reduced undersized or non-target catches in most studies.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Size-sorting escape grids improved size-selection for haddock in some cases but not for saithe or cod.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "In one comparison, size-sorting escape grids did not outperform square-mesh escape windows.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "In prawn and shrimp trawls, size-sorting escape grids often reduced unwanted fish, including sharks, across multiple regions.",
    "citations": [
      "2721"
    ]
  },
  {
    "statement": "The effects of size-sorting escape grids in prawn and shrimp trawls varied by species, site, year, and grid type.",
    "citations": [
      "2721"
    ]
  },
  {
    "statement": "Several studies on prawn and shrimp trawls found that grids caused no reduction in unwanted fish or had mixed outcomes.",
    "citations": [
      "2721"
    ]
  },
  {
    "statement": "Large, supported escape openings generally reduced unwanted fish and total unwanted catch in most trials.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "Large, supported escape openings showed species-specific results, such as fewer unwanted Chinook salmon but mixed effects for widow rockfish.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "One study reported that large, supported escape openings reduced unwanted sharks but not rays or sawfish compared to standard nets.",
    "citations": [
      "2723"
    ]
  },
  {
    "statement": "Mesh escape panels and windows showed mixed effects on selectivity.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "Modifying the position or size of mesh escape panels sometimes improved size-selectivity for haddock and whiting.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "The effects of mesh escape panels for cod were similar to standard trawls.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "Reductions in unwanted catches using mesh escape panels were inconsistent across species and studies.",
    "citations": [
      "2717"
    ]
  },
  {
    "statement": "Combining different escape devices tended to enhance selectivity and bycatch reduction.",
    "citations": [
      "2727",
      "2726"
    ]
  },
  {
    "statement": "Combining mesh escape panels or windows with grids reduced unwanted fish, rays, sharks, and total discards in several studies.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "The combination of mesh escape panels or windows with grids increased the size-selectivity of whiting.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "When panels and grids were combined, escape occurred via either device depending on the species and size of the fish.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Combining size-sorting grids with large supported openings reduced unwanted fish and sharks/rays in most studies.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "There were exceptions to the effectiveness of combining grids and large openings, with one study finding no reduction in sharks and another finding no reduction in sawfish.",
    "citations": [
      "2726"
    ]
  }
]

[
  {
    "statement": "A study in the Coral Sea found that areas closed to non-towed fishing gears had higher overall shark abundance when sampled with longlines compared to areas where commercial gillnets were permitted.",
    "citations": [
      "2670"
    ]
  },
  {
    "statement": "The same study in the Coral Sea found that areas closed to non-towed fishing gears did not have higher overall shark abundance when sampled with gillnets compared to areas where commercial gillnets were permitted.",
    "citations": [
      "2670"
    ]
  },
  {
    "statement": "A study in the Indian Ocean reported that closing a zone to offshore line fishing and all other boat-based fishing resulted in higher abundances of four fish species over-exploited by line fishing.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "The higher abundances of over-exploited fish were found when comparing the closed zone to two zones where boat-based line and spear fishing were permitted.",
    "citations": [
      "2671"
    ]
  }
]

[
  {
    "statement": "Fish species richness was higher in no‑fishing/no‑access zones than in partially fished zones and unprotected areas 10 to 15 years after implementation.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The average lengths of several fish species were larger within no‑take zones than in partially fished zones three years after implementation.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Fish densities, biomass, and abundance were typically higher in non‑fished zones (no‑entry or no‑take) than in fished zones within the same protected areas.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The effects of zonation on fish populations varied among different fish groups, sizes, protection levels, and regions.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "A zone closed to fishing but open to other recreation had a different fish age and sex structure than a multipurpose fished zone.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "The zone closed to fishing and the multipurpose fished zone both had different fish age and sex structures compared to an unprotected low-exploitation site.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Tagged reef fishes were mostly recaptured near the sites where the fish were released.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Tagged reef fishes were mainly recaptured within zones where all or nearly all fishing was prohibited for up to 20 years.",
    "citations": [
      "2674"
    ]
  }
]

[
  {
    "statement": "Across regions, reported outcomes from prohibiting mobile bottom fishing gear vary.",
    "citations": []
  },
  {
    "statement": "In the Mediterranean, areas closed to all bottom-towed gears for 14 years showed higher biomass of adult red mullet compared to before the closure or to fished areas.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In the Mediterranean, areas closed to all bottom-towed gears for 14 years showed larger sizes of adult red mullet compared to before the closure or to fished areas.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In the Mediterranean, areas closed to all bottom-towed gears for 14 years showed increased recruitment of young red mullet compared to before the closure or to fished areas.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In the North Atlantic, an area closed to bottom trawling for seven years did not show higher recruitment or survival of young haddock compared to a trawled area.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Other closures in the North Atlantic that prohibited mobile and static bottom gears for 5–15 years reported cod with better growth than in openly fished areas.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "Other closures in the North Atlantic that prohibited mobile and static bottom gears for 5–15 years reported higher numbers of larger and older cod individuals than in openly fished areas.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "For benthic invertebrates, North Sea sites closed to trawling for 15 years had a different community composition than trawled sites.",
    "citations": [
      "2099"
    ]
  },
  {
    "statement": "North Sea sites closed to trawling for 15 years had higher diversity of benthic invertebrates than trawled sites.",
    "citations": [
      "2099"
    ]
  },
  {
    "statement": "One study found that Mediterranean sites closed for 20 years had a different benthic invertebrate composition compared to trawled sites.",
    "citations": [
      "2099"
    ]
  },
  {
    "statement": "One study of Mediterranean sites closed for 20 years showed no differences in overall invertebrate diversity or abundance compared to trawled sites.",
    "citations": [
      "2099"
    ]
  },
  {
    "statement": "Evidence from studies across multiple regions, including the Indian Ocean, indicates that effects on fish size in areas prohibiting bottom-towed gears varied between fish groups.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "Evidence from studies across multiple regions, including the Indian Ocean, indicates that effects on fish size in areas prohibiting bottom-towed gears varied with habitat type.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In some cases, closures prohibiting bottom-towed gears had no effect on average fish weight.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In some cases, closures prohibiting bottom-towed gears had no effect on combined fish and invertebrate sizes.",
    "citations": [
      "2673"
    ]
  }
]

[
  {
    "statement": "Topless (coverless) trawls and separator trawls both show evidence of reducing unwanted fish.",
    "citations": [
      "2712",
      "2711"
    ]
  },
  {
    "statement": "The effectiveness of topless and separator trawls in reducing unwanted fish differs in consistency and context.",
    "citations": []
  },
  {
    "statement": "For topless trawls, four replicated, controlled studies reported mixed but often positive effects.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls reduced catches of unwanted Atlantic cod in some trials.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls reduced discards of commercial species in some trials.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls resulted in size-dependent reductions for haddock, where larger fish were reduced but smaller fish were not.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "In another case, topless trawls caused reductions for only one of four commercial species.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "For separator trawls, two studies reported targeted reductions of unwanted fish via gear design.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "One randomized North Sea study showed unwanted cod were directed into a lower codend with larger mesh.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "The larger mesh in the separator trawl allowed more smaller cod to escape.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "An Atlantic study found that adding a square-mesh escape panel to a separator trawl reduced catches of one of two unwanted fish species in a crustacean fishery.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Overall, topless trawls show mixed reductions of unwanted fish across species and sizes.",
    "citations": [
      "2712",
      "2711"
    ]
  },
  {
    "statement": "Separator trawls demonstrate design-mediated separation that reduced some unwanted species or sizes in specific configurations.",
    "citations": [
      "2712",
      "2711"
    ]
  }
]

[
  {
    "statement": "Modifying trap and pot configurations was evaluated for effects on marine fish across 23 studies in multiple regions.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One replicated, controlled study found the survival of small herring that escaped through a size‑sorting grid was similar to the survival of trap‑caught herring that did not pass through a grid.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Sixteen of 20 replicated studies reported that configuration changes, such as different trap types, larger mesh, or escape devices, reduced unwanted catches of fish overall or for specific species.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Configuration changes reduced unwanted catches of species including brown trout, black sea bass, herring, bluethroat wrasse and leatherjacket, cod, protected rockfishes, whitefish, American eel, winter flounder, and sharks/rays.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Three studies found that trap or pot configuration changes did not reduce catches for some species, such as white croaker, non‑commercial fish, and undersized Atlantic cod.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study reported that configuration changes increased catches of non-target haddock.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study noted that creels did not catch high proportions of immature fish compared to bottom trawls.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Size‑selectivity improved in three of four replicated studies when traps or pots had square‑mesh escape windows or larger mesh.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Improved size-selectivity from modified traps or pots benefited Atlantic cod, black sea bass, and most fish species.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study found that using square-mesh escape windows or larger mesh had no effect on size-selectivity for panga.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Modifications to trap- or bag-nets designed to exclude mammals reduced seal damage to salmon catches.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "Modifications to trap- or bag-nets designed to exclude mammals led to higher catches of undamaged salmon.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "Modifications to trap- or bag-nets designed to exclude mammals did not lead to higher catches of undamaged whitefish.",
    "citations": [
      "2822"
    ]
  }
]

[
  {
    "statement": "Nine studies tested electropositive deterrents on fishing gear.",
    "citations": []
  },
  {
    "statement": "The studies on electropositive deterrents spanned the Atlantic Ocean, Gulf of Alaska, South Pacific Ocean and Tasman Sea.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "The research into electropositive deterrents on fishing gear also included two laboratory studies and one global systematic review.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Behavioural evidence from three of four replicated studies showed reduced feeding attempts or bait consumption by spiny dogfish, great hammerhead and draughtboard sharks when deterrent materials were attached near bait.",
    "citations": []
  },
  {
    "statement": "One study found no reduction in feeding attempts or bait consumption for bonnethead and young lemon sharks when deterrent materials were attached near bait.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "One study reported no effect on bait consumption by commercially valuable Pacific halibut when deterrent materials were attached near bait.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Catch outcomes from two of four replicated, controlled field studies reported fewer unwanted catches of spiny dogfish, longnose skate, and combined sharks and rays on longlines and traps when electropositive deterrents were used.",
    "citations": []
  },
  {
    "statement": "Catch outcomes from two of four replicated, controlled field studies also reported fewer undersized halibut when electropositive deterrents were used versus standard or non-deterrent gear.",
    "citations": []
  },
  {
    "statement": "Two other field studies found no reduction in catches, with catches of spiny dogfish, total sharks, blue shark, and combined sharks and rays being similar to controls.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "A global systematic review found no reduction in catches of spiny dogfish, total sharks, blue shark, and combined sharks and rays when using electropositive deterrents compared to controls.",
    "citations": [
      "2696"
    ]
  }
]

[
  {
    "statement": "In replicated, controlled studies across European seas, 10 out of 16 studies reported that square mesh codends reduced unwanted catch of non-target or discarded fish and invertebrates.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Four of 16 replicated, controlled studies in European seas found no reduction in unwanted catch when using square mesh codends.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "One study in European seas found that square mesh codends retained more fish overall.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "One study found that the amount of unwanted catch depended on both mesh size and configuration.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "In studies where square mesh codends showed no or varied effects, increasing the mesh size improved selectivity for both square and diamond mesh codend types.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "In the English Channel, one replicated study found a square mesh codend caught fewer non-commercial invertebrates in one of two areas.",
    "citations": [
      "2136"
    ]
  },
  {
    "statement": "In the English Channel, one replicated study found a square mesh codend caught similar amounts of non-commercial invertebrates in the other of two areas.",
    "citations": [
      "2136"
    ]
  },
  {
    "statement": "Adding square-mesh escape panels to a square mesh codend reduced the numbers of discarded finfish in the English Channel.",
    "citations": [
      "2724"
    ]
  },
  {
    "statement": "Adding square-mesh escape panels to a square mesh codend reduced non-commercial invertebrate bycatch in the English Channel.",
    "citations": [
      "2138"
    ]
  }
]

[
  {
    "statement": "Seven site comparison studies found that marine protected areas where all fishing had been prohibited for 3–16 years had a different fish community composition compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "14 of 20 site comparison studies found higher fish species richness in non-fished marine protected areas 1 to >25 years after implementation compared to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Six site comparison studies found similar fish species richness between non-fished marine protected areas and fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One systematic review in the Atlantic and Pacific Oceans found no difference in fish species richness between non-fished marine protected areas and fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One replicated study in the Indian Ocean reported that effects on fish species richness after 15 years varied with the sampling method used.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "One site comparison study found lower total fish species richness in marine protected areas in the Caribbean Sea that were closed to all fishing with limited exceptions for up to seven years, when compared to unprotected areas.",
    "citations": [
      "2681"
    ]
  }
]

[
  {
    "statement": "In six of fourteen replicated, controlled studies, using a square mesh codend improved size selectivity.",
    "citations": [
      "2714"
    ]
  },
